#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
typedef struct Node { char *key; int value; struct Node *next; } Node;
typedef struct { Node **buckets; size_t capacity; size_t size; } HashTable;
static unsigned long hash(const char *str) { unsigned long h = 5381; int c; while ((c = (unsigned char)*str++)) h = h * 33 + c; return h; }
HashTable *ht_create(size_t capacity) { HashTable *ht = malloc(sizeof(HashTable)); ht->capacity = capacity; ht->size = 0; ht->buckets = calloc(capacity, sizeof(Node *)); return ht; }
void ht_put(HashTable *ht, const char *key, int value) {
    size_t idx = hash(key) % ht->capacity;
    Node *n = malloc(sizeof(Node)); n->key = strdup(key); n->value = value; n->next = ht->buckets[idx]; ht->buckets[idx] = n; ht->size++;
}
bool ht_remove(HashTable *ht, const char *key) {
    size_t idx = hash(key) % ht->capacity;
    Node *cur = ht->buckets[idx], *prev = NULL;
    while (cur) {
        if (strcmp(cur->key, key) == 0) {
            if (prev) prev->next = cur->next; else ht->buckets[idx] = cur->next;
            free(cur->key); free(cur); ht->size--; return true;
        }
        prev = cur; cur = cur->next;
    }
    return false;
}
int main(void) {
    HashTable *ht = ht_create(2);
    ht_put(ht, "A", 1); ht_put(ht, "B", 2); ht_put(ht, "C", 3);
    printf("A: %s\n", ht_remove(ht, "A") ? "DELETED" : "NOT FOUND");
    printf("C: %s\n", ht_remove(ht, "C") ? "DELETED" : "NOT FOUND");
    printf("Remove ZZZ: %s\n", ht_remove(ht, "ZZZ") ? "DELETED" : "NOT FOUND");
    return 0;
}

