#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node { char *key; int value; struct Node *next; } Node;
typedef struct { Node **buckets; size_t capacity; size_t size; } HashTable;
static unsigned long hash(const char *str) { unsigned long h = 5381; int c; while ((c = (unsigned char)*str++)) h = h * 33 + c; return h; }
HashTable *ht_create(size_t capacity) { HashTable *ht = malloc(sizeof(HashTable)); ht->capacity = capacity; ht->size = 0; ht->buckets = calloc(capacity, sizeof(Node *)); return ht; }
static void insert_new(HashTable *ht, char *key, int value) {
    size_t idx = hash(key) % ht->capacity;
    Node *n = malloc(sizeof(Node)); n->key = key; n->value = value; n->next = ht->buckets[idx]; ht->buckets[idx] = n; ht->size++;
}
static void rehash(HashTable *ht) {
    size_t old_cap = ht->capacity; Node **old = ht->buckets;
    ht->capacity *= 2; ht->buckets = calloc(ht->capacity, sizeof(Node *)); ht->size = 0;
    for (size_t i = 0; i < old_cap; i++) {
        Node *cur = old[i];
        while (cur) { Node *next = cur->next; insert_new(ht, cur->key, cur->value); free(cur); cur = next; }
    }
    free(old);
}
void ht_put(HashTable *ht, const char *key, int value) {
    size_t idx = hash(key) % ht->capacity;
    for (Node *cur = ht->buckets[idx]; cur; cur = cur->next) if (strcmp(cur->key, key) == 0) { cur->value = value; return; }
    insert_new(ht, strdup(key), value);
    if ((double)ht->size / ht->capacity > 0.75) rehash(ht);
}
int ht_get(HashTable *ht, const char *key, int *out) {
    size_t idx = hash(key) % ht->capacity;
    for (Node *cur = ht->buckets[idx]; cur; cur = cur->next) if (strcmp(cur->key, key) == 0) { *out = cur->value; return 1; }
    return 0;
}
int main(void) {
    HashTable *ht = ht_create(8);
    char key[16];
    for (int i = 1; i <= 20; i++) { snprintf(key, sizeof key, "key%d", i); ht_put(ht, key, i * 10); }
    int ok = 1, v;
    for (int i = 1; i <= 20; i++) { snprintf(key, sizeof key, "key%d", i); if (!ht_get(ht, key, &v) || v != i * 10) ok = 0; }
    printf("Initial capacity: 8\n");
    printf("Final capacity: %zu\n", ht->capacity);
    printf("Size: %zu\n", ht->size);
    printf("Load factor: %.2f\n", (double)ht->size / ht->capacity);
    printf(ok ? "All data verified!\n" : "Data error!\n");
    return 0;
}
